// MoonProof's canonical entry opens the single cockpit directly.
// Source of truth; entry.js is generated by npm --prefix web run build:ts.
export function cockpitEntryURL(href) {
    const current = new URL(href);
    // Static hosts normally canonicalize /moonproof to /moonproof/, but both
    // forms should be safe even if a host serves the entry without a slash.
    if (current.pathname.endsWith("/moonproof"))
        current.pathname += "/";
    const target = new URL("cockpit.html", current);
    target.search = current.search;
    target.hash = current.hash;
    return target.href;
}
export function openCockpit(locationRef, fallback) {
    const target = cockpitEntryURL(locationRef.href);
    if (fallback)
        fallback.href = target;
    locationRef.replace(target); // Back returns to the previous page, not this adapter.
}
if (typeof document !== "undefined")
    openCockpit(location, document.querySelector("#cockpit-entry"));
